{
  "title": "Solving x² − 5x + 6 = 0",
  "lang": "en",
  "steps": [
    {
      "title": "The problem",
      "say": "We want the values of x that make x squared minus 5x plus 6 equal to zero.",
      "ops": [
        { "id": "ttl", "type": "write", "op": "write", "x": 800, "y": 50, "text": "Solve a quadratic", "size": 56, "anchor": "middle", "color": "blue" },
