      ]
    },
    {
      "title": "Try the formula",
      "say": "First try the quadratic formula. Here a is 1, b is minus 5, and c is 6.",
      "ops": [
        { "id": "m1", "op": "write", "x": 80, "y": 250, "text": "Method 1: quadratic formula", "size": 36, "color": "blue" },
        { "id": "f1", "op": "write", "x": 80, "y": 320, "text": "x = ( −b ± √(b² − 4ac) ) / 2a", "size": 40 },
        { "id": "f2", "op": "write", "x": 80, "y": 390, "text": "a = 1,  b = −5,  c = 6", "size": 40, "color": "gray" }
      ]
    },
    {
      "title": "Plug in the numbers",
      "say": "Substituting gives the square root of 1, so x is 5 plus or minus 1, over 2. It works, but it is a lot of machinery.",
      "ops": [
        { "id": "f3", "op": "write", "x": 80, "y": 470, "text": "x = (5 ± √(25 − 24)) / 2", "size": 40 },
        { "id": "f4", "op": "write", "x": 80, "y": 540, "text": "x = (5 ± 1) / 2", "size": 40 },
        { "id": "f5", "op": "write", "x": 800, "y": 540, "text": "Works, but heavy!", "size": 34, "color": "red" }
      ]
    },
