      "ops": [
        { "id": "x1", "op": "erase", "ids": ["m1", "f1", "f2", "f3", "f4", "f5"] },
        { "id": "m2", "op": "write", "x": 80, "y": 250, "text": "Method 2: factoring", "size": 36, "color": "green" }
      ]
    },
    {
      "title": "Find the two numbers",
      "say": "We need two numbers that multiply to 6 and add to minus 5. Those are minus 2 and minus 3.",
      "ops": [
        { "id": "n1", "op": "write", "x": 80, "y": 320, "text": "product = 6,  sum = −5", "size": 40 },
        { "id": "n2", "op": "write", "x": 80, "y": 390, "text": "−2 and −3", "size": 44, "color": "green" }
      ]
