{
  "title": "Why the Pythagorean Theorem Works",
  "lang": "en",
  "steps": [
    {
      "title": "1. The Right Triangle",
      "say": "Let's start with a right-angled triangle with legs a and b, and hypotenuse c.",
      "ops": [
        { "op": "write", "id": "main_title", "x": 800, "y": 50, "text": "Why the Pythagorean Theorem Works", "size": 56, "anchor": "middle", "underline": true },
        { "op": "path", "id": "t0", "d": "M 80 420 L 80 580 L 200 580 Z", "color": "ink", "fill": "gray" },
        { "op": "path", "id": "t0_ra", "d": "M 80 560 L 100 560 L 100 580", "color": "ink", "width": 3 },
        { "op": "write", "id": "t0_a", "x": 50, "y": 480, "text": "a", "size": 36, "color": "blue" },
        { "op": "write", "id": "t0_b", "x": 140, "y": 595, "text": "b", "size": 36, "color": "green", "anchor": "middle" },
        { "op": "write", "id": "t0_c", "x": 155, "y": 475, "text": "c", "size": 36, "color": "red" }
      ]
    },
    {
      "title": "2. Build a Large Square",
      "say": "Take four identical copies of this triangle and arrange them into a large square with side length a + b.",
      "ops": [
        { "op": "rect", "id": "sq1", "x": 360, "y": 240, "w": 360, "h": 360, "color": "ink" },
        { "op": "path", "id": "s1_t1", "d": "M 360 240 L 560 240 L 360 390 Z", "color": "ink", "fill": "gray" },
        { "op": "path", "id": "s1_t2", "d": "M 720 240 L 720 440 L 560 240 Z", "color": "ink", "fill": "gray" },
        { "op": "path", "id": "s1_t3", "d": "M 720 600 L 520 600 L 720 440 Z", "color": "ink", "fill": "gray" },
        { "op": "path", "id": "s1_t4", "d": "M 360 600 L 360 390 L 520 600 Z", "color": "ink", "fill": "gray" },
        { "op": "write", "id": "s1_la1", "x": 460, "y": 195, "text": "a", "size": 32, "color": "blue", "anchor": "middle" },
        { "op": "write", "id": "s1_lb1", "x": 640, "y": 195, "text": "b", "size": 32, "color": "green", "anchor": "middle" },
        { "op": "write", "id": "s1_lb2", "x": 330, "y": 300, "text": "b", "size": 32, "color": "green", "anchor": "middle" },
        { "op": "write", "id": "s1_la2", "x": 330, "y": 480, "text": "a", "size": 32, "color": "blue", "anchor": "middle" }
      ]
    },
    {
      "title": "3. The Tilted Inner Square",
      "say": "The empty space in the middle is a tilted square with side c, so its area is c squared.",
      "ops": [
        { "op": "path", "id": "s1_c2", "d": "M 560 240 L 720 440 L 520 600 L 360 390 Z", "color": "red", "fill": "red" },
        { "op": "write", "id": "s1_lc", "x": 610, "y": 350, "text": "c", "size": 32, "color": "red" },
        { "op": "write", "id": "s1_ac2", "x": 540, "y": 400, "text": "Area = c²", "size": 38, "color": "red", "anchor": "middle" },
        { "op": "write", "id": "s1_cap", "x": 540, "y": 630, "text": "Empty space = c²", "size": 36, "color": "red", "anchor": "middle" }
      ]
    },
    {
      "title": "4. Rearrange the Triangles",
      "say": "Now make an identical large square of side a + b, and slide the four triangles into two rectangles.",
      "ops": [
        { "op": "rect", "id": "sq2", "x": 960, "y": 240, "w": 360, "h": 360, "color": "ink" },
        { "op": "path", "id": "s2_t1", "d": "M 960 440 L 960 600 L 1160 600 Z", "color": "ink", "fill": "gray" },
        { "op": "path", "id": "s2_t2", "d": "M 960 440 L 1160 440 L 1160 600 Z", "color": "ink", "fill": "gray" },
        { "op": "path", "id": "s2_t3", "d": "M 1160 240 L 1320 240 L 1320 440 Z", "color": "ink", "fill": "gray" },
        { "op": "path", "id": "s2_t4", "d": "M 1160 240 L 1160 440 L 1320 440 Z", "color": "ink", "fill": "gray" },
        { "op": "write", "id": "s2_la1", "x": 1060, "y": 195, "text": "a", "size": 32, "color": "blue", "anchor": "middle" },
        { "op": "write", "id": "s2_lb1", "x": 1240, "y": 195, "text": "b", "size": 32, "color": "green", "anchor": "middle" },
        { "op": "write", "id": "s2_la2", "x": 930, "y": 325, "text": "a", "size": 32, "color": "blue", "anchor": "middle" },
        { "op": "write", "id": "s2_lb2", "x": 930, "y": 505, "text": "b", "size": 32, "color": "green", "anchor": "middle" }
      ]
    },
    {
      "title": "5. Two Smaller Squares",
      "say": "Now the empty space is split into two squares: one of area a squared, and one of area b squared.",
      "ops": [
        { "op": "rect", "id": "s2_a2", "x": 960, "y": 240, "w": 200, "h": 200, "color": "blue", "fill": "blue" },
        { "op": "rect", "id": "s2_b2", "x": 1160, "y": 440, "w": 160, "h": 160, "color": "green", "fill": "green" },
        { "op": "write", "id": "s2_aa2", "x": 1060, "y": 320, "text": "a²", "size": 42, "color": "blue", "anchor": "middle" },
        { "op": "write", "id": "s2_ab2", "x": 1240, "y": 500, "text": "b²", "size": 42, "color": "green", "anchor": "middle" },
        { "op": "write", "id": "s2_cap", "x": 1140, "y": 630, "text": "Empty space = a² + b²", "size": 36, "color": "ink", "anchor": "middle" }
      ]
    },
    {
      "title": "6. Equal Empty Areas",
      "say": "Since the outer squares and the four triangles are identical, the empty areas must be equal: a² + b² = c²!",
      "ops": [
        { "op": "line", "id": "eq_arr", "x1": 760, "y1": 420, "x2": 900, "y2": 420, "color": "ink", "width": 5, "arrow": "both" },
        { "op": "write", "id": "eq_txt", "x": 830, "y": 365, "text": "Same\nArea", "size": 30, "color": "ink", "anchor": "middle" },
        { "op": "rect", "id": "final_box", "x": 520, "y": 720, "w": 640, "h": 110, "color": "ink", "width": 6 },
        { "op": "write", "id": "final_eq", "x": 840, "y": 745, "text": "a² + b² = c²", "size": 56, "color": "red", "anchor": "middle" }
      ]
    }
  ]
}

